                        <td className="relative p-0 text-center">
                          <TableRowRemove
                            aria-label={`Remove ${line.asset || `asset line ${i + 1}`}`}
                            disabled={draft.lines.length === 1}
                            onRemove={() => removeLine(i)}
                          />
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
