  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { SheetField, SheetSection, SheetSectionNote } from "@/components/side-sheet/parts";
import { cn } from "@/lib/utils";
import { DraftStatusChip, RecordSheet, useDraftSaveState } from "../RecordSheet";
import type { PendingItem } from "../PendingStrip";
import { DASH, formatDate, formatStamp, type Attachment, type AuditEvent } from "./directoryCore";
import type { FieldKind, FormFieldDef, FormSectionDef } from "./directoryFormTypes";
import { kindTone } from "../statusKind";

/*
  The Directory's record sheet.

  ONE SHEET, NOT A PAGE AND A FORM. The DS's rule for a record is the side
  sheet — `CustomerSheet` is the precedent, and `RecordSheet` is the component:
  the record IS the form, `mode` decides whether the header says Edit or
  Create, and the footer carries Save Changes. A full-page detail with a
  separate edit screen was a second interaction pattern for the same job, and
  the sheet keeps the list behind it, which is the point of a sheet.

  READ-ONLY CONTENT LIVES IN THE SAME SCROLL. A record's related lists —
  orders against an account, a vendor's rate card, an asset's billing history —
  are `SheetSection`s like any other, below the editable ones. Section rhythm
  is the DS's 40 / 16 throughout, owned by the sheet body.

  WIDTH IS `wide`, not `narrow`. 560px is right for stacked fields and wrong
  for the tables these records carry: at 560 their columns have to be scrolled
  sideways, and a table you scroll to read is a table you cannot compare rows
  in. That is the DS's own reason for the size, quoted in `RecordSheet`.

  VALIDATION KEEPS THE FORM'S CONTRACT. Nothing is red until you have left the
  field; after a failed submit everything validates live; a failed submit keeps
  every character. `canSubmit` gates the footer, so an incomplete record cannot
  be saved from a sheet any more than from a page.
*/

export interface RecordReadSection {
  key: string;
  title: string;
  /** Count on the heading note — "6 locations". Omit where none applies. */
  count?: number;
  note?: string;
  /** Its table's columns as `CELL` widths — the sheet is as wide as the
      widest section's table (Pavan, 2026-10-15: each record its own width). */
  columns?: number[];
  render: () => React.ReactNode;
}

export interface DirectoryRecordSheetProps<T> {
  /**
   * The record's edit history.
   *
   * NOT A SECTION. It is the longest block on the record and the one people
   * read least often, and at the bottom of the body it pushed everything
   * anyone opens the sheet FOR — the related records — behind a wall of "field
   * changed" lines. It gets an icon in the header instead, which also makes it
   * reachable without scrolling at all.
   */
  audit?: AuditEvent[];
  open: boolean;
  onOpenChange: (open: boolean) => void;
  mode: "edit" | "create";
  /** "Customer", "Vendor" — the sheet's own noun. */
  noun: string;
  /** The record's name, for the edit header. */
  title: string;
  /** The record's identity — the draft resets only when this changes, so an
   *  autosaved edit coming back as `initial` does not reset the form. */
  recordKey: string;
  /* AUTOSAVE (Pavan, 2026-10-07). An existing record writes each valid change
     as it settles; Confirm and Close finish the visit. */
  onAutosave?: (draft: T) => void;
  /** Closing hands back the latest draft (null while it is invalid), so a
   *  change still settling is not lost. */
  onClose?: (latest: T | null) => void;
  /** The ⋯ menu — acts on the record that are not part of filling it in. */
  headerMenu?: React.ReactNode;
  headerAside?: React.ReactNode;
  initial: T;
  sections: FormSectionDef<T>[];
  /** Everything the record shows but does not edit, under the editable blocks. */
  readSections?: RecordReadSection[];
  onSubmit: (draft: T) => void;
}

/*
  A FIELD STARTS WITH A CAPITAL, and this is the layer that can safely say so.

  `Input` sets `autoCapitalize`, which only reaches a soft keyboard; on a
  desktop nothing capitalises anything. So the form normalises the first
  character on BLUR — after the reader has finished the word, never while they
  are typing it, because a field that rewrites itself mid-keystroke is a field
  people fight.

  WHAT IS EXEMPT, and why each one:
    · email, url  — case-carrying. "Ray.obuya@…" is a different string, and
      capitalising it is the kind of silent edit that produces a bounced
      invoice.
    · number, money, date — no letters to capitalise.
    · select, combobox, switch, checkbox — the value is chosen, not typed.

  AND IT ONLY TOUCHES THE FIRST CHARACTER. `text-transform: capitalize`
  uppercases every word, which turns "Bray, Raymond and Marks" into "Bray,
  Raymond And Marks" and a street into title case. One character, once.
*/
const TYPED_TEXT: FieldKind[] = ["text", "tel", "textarea"];

const sentenceCase = (v: string): string =>
  v.length === 0 ? v : v[0].toUpperCase() + v.slice(1);

/**
 * The label an option shows. The VALUE is untouched — a record status stays
 * the lowercase `active` the model stores, and only the word on screen is
 * capitalised. Values that already start with a capital ("Net 30") pass
 * straight through.
 */
const optionLabel = (v: string): string => sentenceCase(v);

function isBlank(v: string | number | boolean | null): boolean {
  return v === null || v === undefined || v === "" || (typeof v === "number" && Number.isNaN(v));
}

export function DirectoryRecordSheet<T>({
  open,
  onOpenChange,
  mode,
  noun,
  title,
  recordKey,
  onAutosave,
  onClose,
  headerMenu,
  headerAside,
  initial,
  sections,
  readSections = [],
  audit,
  onSubmit,
}: DirectoryRecordSheetProps<T>) {
  const [historyOpen, setHistoryOpen] = React.useState(false);
  const [draft, setDraft] = React.useState<T>(initial);
  const [touched, setTouched] = React.useState<Set<string>>(new Set());
  const [submitted, setSubmitted] = React.useState(false);
  /* The same header feedback the order sheets give. A record sheet holds a
     draft exactly as they do, and silence about it reads the same way. */
  const saveState = useDraftSaveState(draft, open);

  /* A sheet is reused across records, so the draft resets when the record it
     is showing changes — not when the component happens to remount. */
  React.useEffect(() => {
    setDraft(initial);
    setTouched(new Set());
    setSubmitted(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [recordKey, mode]);

  const visibleSections = React.useMemo(
    () =>
      sections.map((s) => ({ ...s, fields: s.fields.filter((f) => f.visible?.(draft) ?? true) })),
    [sections, draft]
  );

  const errors = React.useMemo(() => {
    const out: Record<string, string> = {};
    visibleSections.forEach((s) =>
      s.fields.forEach((f) => {
        if (f.required && isBlank(f.get(draft))) out[f.key] = `${f.label} is required`;
        else {
          const e = f.validate?.(draft);
          if (e) out[f.key] = e;
        }
      })
    );
    return out;
  }, [visibleSections, draft]);

  const errorCount = Object.keys(errors).length;

  /* AUTOSAVE (Pavan, 2026-10-07) — the draft chip's promise kept: a valid
     change on an existing record is written once typing settles. */
  const latestInitial = React.useRef(initial);
  latestInitial.current = initial;
  React.useEffect(() => {
    if (mode !== "edit" || !onAutosave || !open) return undefined;
    if (draft === latestInitial.current || errorCount > 0) return undefined;
    const t = window.setTimeout(() => onAutosave(draft), 600);
    return () => window.clearTimeout(t);
  }, [draft, errorCount, mode, onAutosave, open]);

  /* WHAT THE PRIMARY IS WAITING ON (Pavan, 2026-10-07 — G25). The button stays
     pressable; a press names the gap and goes to its section. */
  const pending: PendingItem[] = visibleSections.flatMap((s) =>
    s.fields
      .filter((f) => errors[f.key])
      .map((f) => ({
        key: f.key,
        label: f.required && isBlank(f.get(draft)) ? `Add ${f.label.toLowerCase()}` : errors[f.key],
        target: `dir-sec-${s.key}`,
      }))
  );
  const showError = (key: string) => Boolean(errors[key]) && (submitted || touched.has(key));

  const set = (f: FormFieldDef<T>, v: string | number | boolean | null) =>
    setDraft((d) => f.set(d, v));

  const control = (f: FormFieldDef<T>) => {
    const v = f.get(draft);
    const bad = showError(f.key);
    const blur = () => {
      setTouched((t) => new Set(t).add(f.key));
      if (!TYPED_TEXT.includes(f.kind)) return;
      const current = f.get(draft);
      if (typeof current !== "string" || current.length === 0) return;
      const next = sentenceCase(current);
      if (next !== current) setDraft((d) => f.set(d, next));
    };

    switch (f.kind) {
      case "select":
        return (
          <Select
            value={typeof v === "string" && v !== "" ? v : undefined}
            onValueChange={(next) => {
              set(f, next);
              blur();
            }}
          >
            <SelectTrigger
              id={f.key}
              aria-invalid={bad || undefined}
              /* `capitalize` on the TRIGGER only. Radix renders the chosen
                 item's raw text here and there is no slot to relabel it, so
                 the CSS does what `optionLabel` does in the list — and a
                 value like "Net 30" is unaffected either way. */
              className={cn("w-full capitalize", bad && "border-destructive")}
            >
              <SelectValue placeholder={f.placeholder ?? "Select…"} />
            </SelectTrigger>
            <SelectContent>
              {(f.options ?? []).map((o) => (
                <SelectItem key={o} value={o}>
                  {optionLabel(o)}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        );
      case "combobox":
        return (
          <Combobox
            id={f.key}
            value={typeof v === "string" ? v : ""}
            options={(f.options ?? []).map((o) => ({ value: o, label: optionLabel(o) }))}
            placeholder={f.placeholder ?? "Select…"}
            allowCreate={f.allowCreate}
            aria-label={f.label}
            className={cn("w-full", bad && "border-destructive")}
            onValueChange={(next) => {
              set(f, next);
              blur();
            }}
          />
        );

      case "textarea":
        return (
          <Textarea
            id={f.key}
            rows={3}
            value={typeof v === "string" ? v : ""}
            placeholder={f.placeholder}
            aria-invalid={bad || undefined}
            className={cn(bad && "border-destructive")}
            onBlur={blur}
            onChange={(e) => set(f, e.target.value)}
          />
        );
      default: {
        const numeric = f.kind === "number" || f.kind === "money";
        return (
          <Input
            id={f.key}
            type={f.kind === "date" ? "date" : numeric ? "text" : f.kind}
            inputMode={numeric ? "decimal" : undefined}
            value={v === null || v === false ? "" : String(v)}
            placeholder={f.placeholder}
            aria-invalid={bad || undefined}
            className={cn(bad && "border-destructive")}
            onBlur={blur}
            onChange={(e) => {
              const raw = e.target.value;
              if (!numeric) return set(f, raw);
              /* Money accepts what people type — commas, a dollar sign — and
                 stores a number. Rejecting keystrokes is how a field ends up
                 impossible to correct once it is wrong. */
              const cleaned = raw.replace(/[^0-9.-]/g, "");
              return set(f, cleaned === "" ? null : Number(cleaned));
            }}
          />
        );
      }
    }
  };

  const data = readSections.length > 0;
  return (
    <RecordSheet
      /* WIDTH FROM ITS TABLES, PER RECORD (Pavan, 2026-10-15): each read
         section names its table's columns; the widest decides. A create (no
         read sections) is a form, 600. */
      /* AN EXISTING RECORD IS DATA-INTENSIVE (Pavan, 2026-10-15 — "cramped"):
         1200 at least, fields three across. A create stays a 600 form. */
      {...(readSections.length > 0 ? { size: "data" as const } : {})}
      fit={{ tables: readSections.map((r) => r.columns ?? []) }}
      open={open}
      onOpenChange={(o) => {
        if (!o) onClose?.(errorCount === 0 ? draft : null);
        onOpenChange(o);
      }}
      mode={mode}
      editTitle={title}
      createTitle={`Create New ${noun}`}
      createAction={`Create ${noun}`}
      /* NO CANCEL — this sheet autosaves its draft (`useDraftSaveState`
         above), and "Cancel" promises to undo something that has already been
         kept. Close is the honest exit. (DS ux rules, side-sheet anatomy.) */
      showCancel={false}
      headerMenu={headerMenu}
      headerAside={
        <span className="flex items-center gap-2">
          {headerAside}
          {saveState !== "idle" && (
            <DraftStatusChip tone="neutral" label="Draft" saveState={saveState} />
          )}
        </span>
      }
      headerActions={
        audit && audit.length > 0 ? (
          <Tooltip>
            <TooltipTrigger asChild>
              <Button
                variant="ghost"
                size="icon-sm"
                aria-label={`Audit history (${audit.length} ${audit.length === 1 ? "entry" : "entries"})`}
                onClick={() => setHistoryOpen(true)}
              >
                <History />
              </Button>
            </TooltipTrigger>
            <TooltipContent>
              Audit history · {audit.length} {audit.length === 1 ? "entry" : "entries"}
            </TooltipContent>
          </Tooltip>
        ) : undefined
      }
      canSubmit={errorCount === 0}
      pending={pending}
      onSubmit={() => {
        setSubmitted(true);
        if (errorCount > 0) return;
        onSubmit(draft);
      }}
    >
      {visibleSections.map((s) => (
        <SheetSection
          key={s.key}
          id={`dir-sec-${s.key}`}
          title={s.title}
          note={s.note ? <SheetSectionNote>{s.note}</SheetSectionNote> : undefined}
        >
          {/* THREE UP ON A RECORD (the data width, 1200 — Pavan, 2026-10-15),
              two up while creating (600). */}
          <div className={cn("grid gap-4", data ? "grid-cols-3" : "grid-cols-2")}>
            {s.fields.map((f) =>
              /*
                A TOGGLE IS NOT A FIELD WITH A CONTROL UNDER IT.

                Stacked like every other field, a switch put its label on one
                line and a 20px control alone on the next, leaving a hole
                beside it and reading as if something were missing. A toggle is
                a statement and an answer: the statement goes on the left,
                aligned with every other label, the answer sits at the far
                right of the row, and the helper text runs under the statement
                where it explains what turning it on does. That is the row
                `CustomerSheet` already uses for Active.

                Always full width, so the two edges the reader's eye follows —
                the left edge of the labels and the right edge of the sheet —
                are the two things the row is pinned to.
              */
              f.kind === "switch" || f.kind === "checkbox" ? (
                <div
                  key={f.key}
                  className="col-span-full flex items-start justify-between gap-4"
                >
                  <div className="flex min-w-0 flex-col gap-1">
                    <label
                      htmlFor={f.key}
                      className="text-sm font-medium text-foreground"
                    >
                      {f.label}
                      {f.required && <span className="text-destructive"> *</span>}
                    </label>
                    {(showError(f.key) || f.description) && (
                      <span
                        className={cn(
                          "text-xs",
                          showError(f.key) ? "text-destructive" : "text-muted-foreground"
                        )}
                      >
                        {showError(f.key) ? errors[f.key] : f.description}
                      </span>
                    )}
                  </div>
                  <div className="shrink-0 pt-0.5">
                    {f.kind === "switch" ? (
                      <Switch
                        id={f.key}
                        checked={Boolean(f.get(draft))}
                        onCheckedChange={(on) => set(f, on)}
                      />
                    ) : (
                      <Checkbox
                        id={f.key}
                        checked={Boolean(f.get(draft))}
                        onCheckedChange={(on) => set(f, on === true)}
                      />
                    )}
                  </div>
                </div>
              ) : (
                <SheetField
                  key={f.key}
                  label={f.label}
                  required={f.required}
                  description={showError(f.key) ? undefined : f.description}
                  className={f.wide ? "col-span-full" : undefined}
                >
                  {control(f)}
                  {showError(f.key) && (
                    <p className="text-xs text-destructive">{errors[f.key]}</p>
                  )}
                </SheetField>
              )
            )}
          </div>
        </SheetSection>
      ))}

      {audit && (
        <AuditDrawer
          open={historyOpen}
          onOpenChange={setHistoryOpen}
          title={title}
          events={audit}
        />
      )}

      {readSections.map((s) => {
        /* A TABLE TAKES THE CARD'S OWN EDGES. Decided here from what the
           section actually renders rather than from a flag on every section,
           so a new table cannot be added with the gap left in by accident. */
        const body = s.render();
        return (
          <SheetSection
            key={s.key}
            title={s.title}
            flush={fillsSection(body)}
            note={
              s.note || s.count !== undefined ? (
                <SheetSectionNote>
                  {s.note ?? `${s.count} ${s.count === 1 ? "entry" : "entries"}`}
                </SheetSectionNote>
              ) : undefined
            }
          >
            {body}
          </SheetSection>
        );
      })}
    </RecordSheet>
  );
}

/* ═══════════════════════════════════════════════ read-only building blocks ═ */

/**
 * A labelled fact.
 *
 * `-` and `N/A` are both real values, printed muted, never suppressed. A field
 * that vanishes when it is empty makes an incomplete record look complete, and
 * the reason to open a record is to find out what is missing from it.
 */
export function ReadField({
  label,
  value,
  wide = false,
}: {
  label: string;
  value: React.ReactNode;
  wide?: boolean;
}) {
  const empty =
    value === null || value === undefined || value === "" || value === DASH || value === "N/A";
  return (
    <div className={cn(wide && "col-span-full")}>
      <dt className="text-xs font-medium text-muted-foreground">{label}</dt>
      <dd
        className={cn(
          "mt-0.5 text-sm break-words",
          empty ? "text-muted-foreground/70" : "text-foreground"
        )}
      >
        {empty ? DASH : value}
      </dd>
    </div>
  );
}

export function ReadGrid({ children }: { children: React.ReactNode }) {
  /* Three across — the record's data width (Pavan, 2026-10-15). */
  return <dl className="grid grid-cols-3 gap-x-6 gap-y-4">{children}</dl>;
}

/** The widest related-records table any directory record shows (a customer's
 *  assets) — what `DirectoryRecordSheet` sizes itself by. */

/** A related-records table that says something useful when it is empty. */
export function SheetTable<T>({
  rows,
  columns,
  emptyBody,
  onOpenRow,
  rowKey,
  max = 25,
}: {
  rows: T[];
  columns: { key: string; label: string; align?: "right"; render: (row: T) => React.ReactNode }[];
  emptyBody: string;
  onOpenRow?: (row: T) => void;
  rowKey: (row: T) => string;
  max?: number;
}) {
  /* THE CARD IS THE BOX. A table in a boxed unit runs to the unit's edges and
     borrows its border — so the empty state is padded text, not a second
     dashed box inside the first. */
  if (rows.length === 0) {
    return (
      <p className="px-4 py-6 text-center text-sm text-muted-foreground">
        {emptyBody}
      </p>
    );
  }
  const shown = rows.slice(0, max);
  return (
    <div className="overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full min-w-max text-sm">
          <thead>
            <tr className="border-b border-fp-outline-1 bg-fp-table-header">
              {columns.map((c) => (
                <th
                  key={c.key}
                  className={cn(
                    "h-9 whitespace-nowrap px-3 text-left text-xs font-medium text-muted-foreground",
                    c.align === "right" && "text-right"
                  )}
                >
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {shown.map((row) => (
              <tr
                key={rowKey(row)}
                className={cn(
                  "border-b border-fp-outline-1 last:border-0",
                  onOpenRow && "cursor-pointer hover:bg-fp-row-hover"
                )}
                onClick={onOpenRow ? () => onOpenRow(row) : undefined}
              >
                {columns.map((c) => (
                  <td
                    key={c.key}
                    className={cn(
                      "h-10 whitespace-nowrap px-3 align-middle text-foreground",
                      c.align === "right" && "text-right tabular-nums"
                    )}
                  >
                    {c.render(row)}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {rows.length > shown.length && (
        <p className="border-t border-fp-outline-1 px-3 py-2 text-xs text-muted-foreground">
          Showing {shown.length} of {rows.length}. Open the list to see them all.
        </p>
      )}
    </div>
  );
}

/**
 * IT FILLS ITS SECTION. A section whose body is one of these is rendered
 * flush, so the table's edges are the card's edges and there is one border
 * where there used to be two. The flag is on the component rather than on
 * every call site, because a rule nobody has to remember is a rule that holds.
 */
SheetTable.fillsSection = true;

/** Whether a section's body is a table that wants the card's own edges. */
function fillsSection(body: React.ReactNode): boolean {
  return (
    React.isValidElement(body) &&
    (body.type as { fillsSection?: boolean })?.fillsSection === true
  );
}

const FILE_ICON: Record<string, React.ReactNode> = {
  pdf: <FileText className="size-4" />,
  png: <ImageIcon className="size-4" />,
  xlsx: <SheetIcon className="size-4" />,
  csv: <SheetIcon className="size-4" />,
};

/**
 * Files on a record.
 *
 * EXPIRY IS THE POINT for half of these. A certificate that lapsed in June is
 * the most consequential fact a vendor record holds, so it is stated on the
 * row and coloured, not left for somebody to work out from a date.
 */
export function AttachmentTable({ files }: { files: Attachment[] }) {
  const today = new Date();
  return (
    <SheetTable
      rows={files}
      rowKey={(f) => f.id}
      emptyBody="Nothing attached yet."
      columns={[
        {
          key: "name",
          label: "File",
          render: (f) => (
            <span className="flex items-center gap-2">
              <span className="text-muted-foreground">
                {FILE_ICON[f.kind] ?? <FileText className="size-4" />}
              </span>
              {f.name}
            </span>
          ),
        },
        {
          key: "expires",
          label: "Expires",
          render: (f) => {
            if (!f.expiresOn) return <span className="text-muted-foreground/70">{DASH}</span>;
            const gone = new Date(`${f.expiresOn}T00:00:00Z`) < today;
            /* A DATE IS NOT A STATUS (Pavan, 2026-10-09). Now that a status is
               a pill, a grey pill round every date would read as one; only the
               expired date — the warning — takes the pill. */
            return gone ? (
              <StatusChip tone={kindTone("critical")}>Expired {formatDate(f.expiresOn)}</StatusChip>
            ) : (
              <span className="text-sm tabular-nums">{formatDate(f.expiresOn)}</span>
            );
          },
        },
        { key: "size", label: "Size", render: (f) => `${f.sizeKb.toLocaleString()} KB` },
        { key: "by", label: "Uploaded by", render: (f) => f.uploadedBy },
        {
          key: "dl",
          label: "",
          render: () => (
            <Button variant="ghost" size="icon-sm" aria-label="Download file">
              <Download />
            </Button>
          ),
        },
      ]}
    />
  );
}

/** It is a `SheetTable`, so it fills its section for the same reason. */
AttachmentTable.fillsSection = true;

/**
 * The record's history — the same treatment the order sheet's Activity uses.
 *
 * NEWEST FIRST, and every entry names its fields. "Updated" tells you somebody
 * was here; "Credit limit: 120000 → 200000" tells you what to look at.
 */
export function AuditList({ events }: { events: AuditEvent[] }) {
  if (events.length === 0) {
    return (
      <p className="rounded-md border border-dashed border-fp-outline-1 px-4 py-6 text-center text-sm text-muted-foreground">
        Edits to this record will be listed here with who made them and when.
      </p>
    );
  }
  const sorted = [...events].sort((a, b) => (a.at < b.at ? 1 : -1));
  return (
    <ol className="flex flex-col gap-4">
      {sorted.map((e) => (
        <li key={e.id} className="border-l-2 border-fp-outline-1 pl-3">
          <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
            <span className="text-sm font-medium text-foreground">{e.action}</span>
            <span className="text-sm text-muted-foreground">by {e.by}</span>
            <span className="text-xs tabular-nums text-muted-foreground/80">
              {formatStamp(e.at)}
            </span>
          </div>
          {e.changes.length > 0 && (
            <ul className="mt-0.5 flex flex-col gap-0.5">
              {e.changes.map((c, i) => (
                <li key={i} className="text-sm text-muted-foreground">
                  {c}
                </li>
              ))}
            </ul>
          )}
        </li>
      ))}
    </ol>
  );
}

/**
 * A READ-ONLY DRAWER — one thing, looked at, closed.
 *
 * NARROW AND OVER THE TOP. What goes in here is a column of short content —
 * 420px is as wide as it ever needs — and it opens ON whatever is behind it
 * rather than replacing it, so closing puts the reader back exactly where they
 * were with nothing re-rendered underneath.
 *
 * NO FOOTER, deliberately. There is nothing to save: reading is not editing.
 * The moment something in here needs a Save it belongs in the record sheet
 * instead, which is the form.
 *
 * It stacks a layer above the record sheet so the two coexist rather than
 * fighting for the same one — and it opens straight off a LIST row too, where
 * there is no record sheet underneath at all.
 */
export function ReadDrawer({
  open,
  onOpenChange,
  title,
  subtitle,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    /* A picker over a stepped form is not part of it. */
    <FormStepsContext.Provider value={false}>
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent
        side="right"
        showCloseButton={false}
        className="z-[60] w-[min(420px,calc(var(--fp-vw)-56px))] gap-0 p-0 sm:max-w-[min(420px,calc(var(--fp-vw)-56px))]"
      >
        <div className="flex items-start justify-between gap-4 border-b border-border p-4">
          <div className="flex min-w-0 flex-col gap-0.5">
            <SheetTitle className="text-base">{title}</SheetTitle>
            {subtitle && (
              <span className="truncate text-xs text-muted-foreground">{subtitle}</span>
            )}
          </div>
          <button
            type="button"
            aria-label={`Close ${title.toLowerCase()}`}
            onClick={() => onOpenChange(false)}
            className="shrink-0 rounded-sm p-1 text-muted-foreground opacity-70 outline-none transition-opacity hover:opacity-100 focus-visible:ring-2 focus-visible:ring-ring/50"
          >
            <X className="size-4" />
          </button>
        </div>
        <div className="min-h-0 flex-1 overflow-auto p-4">{children}</div>
      </SheetContent>
    </Sheet>
    </FormStepsContext.Provider>
  );
}

/**
 * `ReadDrawer` with a footer — for a small edit that belongs to a record you
 * reached from somewhere else.
 *
 * IT IS NOT THE RECORD SHEET, and must not grow into one. This is for the two
 * or three fields somebody noticed were wrong while doing something else — a
 * stale phone number found halfway through raising an order. The full record
 * still lives in its own sheet; this is the shortcut that stops a wrong number
 * costing somebody their draft.
 */
export function EditDrawer({
  open,
  onOpenChange,
  title,
  subtitle,
  onSave,
  canSave = true,
  children,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  subtitle?: string;
  onSave: () => void;
  canSave?: boolean;
  children: React.ReactNode;
}) {
  /* ON RECORDSHEET (Pavan, 2026-10-07 — G21/G23). A second-level sheet over
     the one it was opened from: no Cancel (Close is the exit), and the
     primary is the sheet's own edit word, not Save Changes. */
  return (
    <RecordSheet
      level={2}
      size="form"
      stepNav={false}
      open={open}
      onOpenChange={onOpenChange}
      mode="edit"
      editTitle={title}
      createTitle={title}
      createAction="Confirm"
      headerSubtitle={
        subtitle ? (
          <span className="truncate text-xs text-muted-foreground">{subtitle}</span>
        ) : undefined
      }
      showCancel={false}
      canSubmit={canSave}
      onSubmit={onSave}
    >
      <div className="flex flex-col gap-4">{children}</div>
    </RecordSheet>
  );
}

/** The record's history, in a `ReadDrawer`. */
export function AuditDrawer({
  open,
  onOpenChange,
  title,
  events,
}: {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  title: string;
  events: AuditEvent[];
}) {
  return (
    <ReadDrawer
      open={open}
      onOpenChange={onOpenChange}
      title="Audit history"
      subtitle={`${title} · ${events.length} ${events.length === 1 ? "entry" : "entries"}`}
    >
      <AuditList events={events} />
    </ReadDrawer>
  );
}

/** Tag pills, or an honest blank. */
export function TagRow({ tags }: { tags: string[] }) {
  if (tags.length === 0) return <span className="text-muted-foreground/70">{DASH}</span>;
  return (
    <span className="flex flex-wrap gap-1">
      {tags.map((t) => (
        <Pill key={t}>
          {t}
        </Pill>
      ))}
    </span>
  );
}

/** Free text a record carries — dispatch instructions, internal notes. */
export function NoteBlock({ body, hint }: { body: string | null; hint: string }) {
  return body ? (
    <p className="text-sm whitespace-pre-wrap text-foreground">{body}</p>
  ) : (
    <p className="text-sm text-muted-foreground/70">{hint}</p>
  );
}

export type { StatusTone };

import * as React from "react";
import { Image as ImageIcon, Send, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { SheetField, SheetSection } from "@/components/side-sheet/parts";
import { RecordSheet } from "../RecordSheet";
import { DATE_FMT } from "../data";
import type { OrderLine } from "./orders";

/*
  INVITING A PARTNER IS SENDING THEM AN EMAIL, so the sheet is the email.

  WHY IT IS NOT A CONFIRM DIALOG. What goes out carries the whole order — the
  site, the window, the assets and the gallons — and it is the only thing the
  partner will ever see of it. A dialog saying "Invite Redline Carriers?" asks
  somebody to vouch for a message they have not read.

  TWO COLUMNS, WHICH IS WHY IT IS `xxwide`: what you write on the left, what
  they receive on the right. The same rule the order sheet follows — editable
  left, derived right — and the preview is derived in the strictest sense,
  because every line of it comes off the order rather than out of this form.

  THE PREVIEW IS NOT A MOCK. It is built from the same draft the sheet was
  opened on, so a wrong address here is a wrong address in the inbox, and it
  can be caught before the send rather than after.
*/

export interface InviteTarget {
  id: string;
  name: string;
  /** Where the invitation goes. Seeded from the partner's dispatch address. */
  email: string;
}

export interface InviteOrderFacts {
  orderNo: string;
  customer: string;
  shipTo: string;
  address: string;
  dateKey: string;
  window: { start: string; end: string };
  lines: OrderLine[];
}

/* ---------------------------------------------------------------------------
 * Email addresses, as chips
 * ------------------------------------------------------------------------ */

/**
 * A LIST OF ADDRESSES IS NOT A LINE OF TEXT. Comma-separated in one field,
 * a single typo takes the whole send down and nothing says which address was
 * wrong. As chips each address is its own object: added on Enter or a comma,
 * removed on its own ×, and one bad one is visibly one bad one.
 */
export function EmailChips({
  value,
  onChange,
  placeholder,
  id,
}: {
  value: string[];
  onChange: (next: string[]) => void;
  placeholder: string;
  id: string;
}) {
  const [text, setText] = React.useState("");

  const commit = () => {
    const parts = text
      .split(/[,;\s]+/)
      .map((s) => s.trim())
      .filter(Boolean);
    if (parts.length === 0) return;
    onChange([...new Set([...value, ...parts])]);
    setText("");
  };

  return (
    <div className="flex min-h-9 flex-wrap items-center gap-1.5 rounded-md border border-input px-2 py-1.5">
      {value.map((addr) => (
        <span
          key={addr}
          className={cn(
            "inline-flex items-center gap-1 rounded-md bg-fp-surface-1b py-0.5 pr-1 pl-2 text-sm",
            /* A ROUGH SHAPE CHECK, NOT VALIDATION. It cannot know whether an
               address exists; it can say that this one has no @ in it, which
               is the typo people actually make. */
            !addr.includes("@") && "text-status-failed"
          )}
        >
          {addr}
          <button
            type="button"
            aria-label={`Remove ${addr}`}
            onClick={() => onChange(value.filter((a) => a !== addr))}
            className="flex size-4 items-center justify-center rounded-sm text-muted-foreground hover:text-foreground"
          >
            <X className="size-3.5" />
          </button>
        </span>
      ))}
      <input
        id={id}
        value={text}
        placeholder={value.length === 0 ? placeholder : undefined}
        onChange={(e) => setText(e.target.value)}
        onKeyDown={(e) => {
          if (e.key === "Enter" || e.key === ",") {
            e.preventDefault();
            commit();
          }
          if (e.key === "Backspace" && text === "" && value.length > 0) {
            onChange(value.slice(0, -1));
          }
        }}
        /* ON BLUR TOO. A half-typed address left in the box and a press of
           Send is the one way to lose a recipient silently. */
        onBlur={commit}
        className="min-w-[10ch] flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
      />
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * What is attached
 * ------------------------------------------------------------------------ */

/**
 * THE EMAIL BODY IS NOT DESIGNED HERE. (Pavan, 2026-09-22.) The order summary
 * that reaches the partner is rendered by another system and goes out as an
 * image; this sheet composes the message around it. Redrawing that layout in
 * the app would be a second copy of somebody else's design, wrong the first
 * time it changed and nobody's job to keep right.
 *
 * SO THIS PANE SHOWS THE ATTACHMENT, not a replica of it — its name, what it
 * carries, and the fact that it is generated rather than written. What the
 * broker is responsible for is on the left.
 */
function AttachedSummary({
  facts,
  partnerName,
}: {
  facts: InviteOrderFacts;
  partnerName: string;
}) {
  const when = (() => {
    const [y, m, d] = facts.dateKey.split("-").map(Number);
    if (!y) return "—";
    return `${DATE_FMT.format(new Date(y, m - 1, d))}, ${facts.window.start} – ${facts.window.end}`;
  })();
  const lines = facts.lines.filter((l) => l.asset);

  return (
    <div className="flex flex-col gap-4 p-4">
      <div className="flex items-start gap-3 rounded-md border border-fp-outline-1 bg-fp-card-1 p-3">
        <ImageIcon className="mt-0.5 size-5 shrink-0 text-muted-foreground" />
        <span className="flex min-w-0 flex-col gap-0.5">
          <span className="truncate text-sm font-medium text-foreground">
            {facts.orderNo}-order-summary.png
          </span>
          <span className="text-xs text-muted-foreground">
            Generated when the invitation is sent · goes out in the message body
          </span>
        </span>
      </div>

      {/* WHAT IS IN IT, IN WORDS. Not a picture of the picture: a list of what
          the partner will be able to read, so a missing asset or a wrong
          window is catchable from here even though the layout is not ours. */}
      <div className="flex flex-col gap-1.5 text-sm">
        <span className="font-medium text-foreground">It will show</span>
        <ul className="flex flex-col gap-1 text-muted-foreground">
          <li>
            Order <span className="text-foreground">{facts.orderNo}</span> for{" "}
            <span className="text-foreground">{facts.customer}</span>
          </li>
          <li>
            <span className="text-foreground">{facts.shipTo}</span> —{" "}
            {facts.address}
          </li>
          <li>
            Delivery <span className="text-foreground">{when}</span>
          </li>
          <li>
            {lines.length === 0 ? (
              <span className="text-status-failed">
                No assets on the order — {partnerName} would be asked to price
                nothing
              </span>
            ) : (
              <>
                <span className="text-foreground">
                  {lines.length} {lines.length === 1 ? "line" : "lines"}
                </span>
                {" — "}
                {lines
                  .map(
                    (l) =>
                      `${l.asset} · ${l.product} · ${
                        l.topOff ? "top off" : `${(l.gal ?? 0).toLocaleString()} gal`
                      }`
                  )
                  .join("; ")}
              </>
            )}
          </li>
          <li>A link back to submit their pricing</li>
        </ul>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------------------
 * The sheet
 * ------------------------------------------------------------------------ */

export function InvitePartnerSheet({
  open,
  onOpenChange,
  targets,
  facts,
  resend = false,
  onSend,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  /** One partner, or everything ticked for a bulk send. */
  targets: InviteTarget[];
  facts: InviteOrderFacts;
  /** A second invitation to somebody already asked — the wording differs. */
  resend?: boolean;
  onSend: (ids: string[]) => void;
}) {
  const one = targets.length === 1 ? targets[0] : null;

  const [to, setTo] = React.useState<string[]>([]);
  const [cc, setCc] = React.useState<string[]>([]);
  const [bcc, setBcc] = React.useState<string[]>([]);
  const [subject, setSubject] = React.useState("");
  const [message, setMessage] = React.useState("");

  /* SEEDED ONCE PER OPEN, so a broker who edits the subject and closes by
     accident does not get their wording back — and one who opens it on a
     different partner does not get the last one's. */
  React.useEffect(() => {
    if (!open) return;
    setTo(targets.map((t) => t.email));
    setCc([]);
    setBcc([]);
    setSubject(
      `${facts.orderNo} · ${facts.shipTo} · ${facts.customer}`
    );
    setMessage(
      resend
        ? `A reminder about order ${facts.orderNo}. We have not had your pricing yet — please acknowledge and submit it when you can.`
        : `We have a delivery to cover and would like you to quote for it. Please acknowledge the order and submit your pricing.`
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, targets.map((t) => t.id).join(","), resend]);

  const nothingToSend = to.length === 0 || subject.trim() === "";

  return (
    <RecordSheet
      /* ONE COLUMN (Pavan, 2026-10-20) — recipients, then the message, then
         what's attached, read top to bottom as the email is. */
      fit={{ tables: [[560]] }}
      /* OVER THE ORDER SHEET — see `level` on `RecordSheet`. */
      level={2}
      open={open}
      onOpenChange={onOpenChange}
      mode="create"
      editTitle=""
      createTitle={
        one
          ? `${resend ? "Resend to" : "Invite"} ${one.name}`
          : `Invite ${targets.length} partners`
      }
      createAction={resend ? "Resend invitation" : "Send invitation"}
      showCancel={false}
      canSubmit={!nothingToSend}
      onSubmit={() => onSend(targets.map((t) => t.id))}
      footerPrimary={
        <Button
          disabled={nothingToSend}
          onClick={() => {
            onSend(targets.map((t) => t.id));
            onOpenChange(false);
          }}
        >
          <Send />
          {targets.length > 1
            ? `Send ${targets.length} invitations`
            : resend
              ? "Resend invitation"
              : "Send invitation"}
        </Button>
      }
    >
      <div className="flex min-w-0 flex-col gap-10">
          <SheetSection title="Recipients">
            <SheetField label="To">
              <EmailChips
                id="invite-to"
                value={to}
                onChange={setTo}
                placeholder="name@partner.com"
              />
            </SheetField>
            <div className="grid grid-cols-2 gap-4">
              <SheetField label="Cc">
                <EmailChips
                  id="invite-cc"
                  value={cc}
                  onChange={setCc}
                  placeholder="Optional"
                />
              </SheetField>
              <SheetField label="Bcc">
                <EmailChips
                  id="invite-bcc"
                  value={bcc}
                  onChange={setBcc}
                  placeholder="Optional"
                />
              </SheetField>
            </div>
            {targets.length > 1 && (
              /* A BULK SEND IS N EMAILS, NOT ONE WITH N NAMES ON IT. Partners
                 bidding against each other must not see the list they are
                 bidding against. */
              <p className="text-xs text-muted-foreground">
                One message each — no partner sees the others.
              </p>
            )}
          </SheetSection>

          {/* THE MESSAGE RUNS TO THE BOTTOM. It is the only thing on this
              sheet the broker actually writes, and a seven-line box under
              two short fields made the writing feel like an afterthought to
              the addressing. Everything above it is fixed; this takes what
              is left. */}
          <SheetSection title="Message">
            <SheetField label="Subject">
              <Input
                value={subject}
                onChange={(e) => setSubject(e.target.value)}
                placeholder="What the order is"
              />
            </SheetField>
            {/* THE BOX IS THE REST OF THE CARD.
                TWO THINGS HAD TO GIVE. `SheetField` wraps its control in a
                second div for the helper-text rhythm, so the growth has to be
                passed through it as well as to the field itself; and the DS
                textarea is `field-sizing-content`, which sizes to what is
                typed and would shrink a deliberately tall box back to three
                lines. Fixed sizing plus `flex-1` is what makes it fill. */}
            <SheetField label="Your note">
              <Textarea
                value={message}
                onChange={(e) => setMessage(e.target.value)}
                placeholder="Anything this partner needs to know."
                className="min-h-[160px] resize-y [field-sizing:fixed]"
              />
            </SheetField>
          </SheetSection>

          {/* WHAT THEY GET, UNDER WHAT YOU WRITE. */}
          <SheetSection
            title="Attached"
            flush
            action={
              <span className="text-xs text-muted-foreground">
                {one ? one.name : `${targets.length} partners`}
              </span>
            }
          >
            <AttachedSummary
              facts={facts}
              partnerName={one?.name ?? "the partner"}
            />
          </SheetSection>
      </div>
    </RecordSheet>
  );
}

import { cn } from "@/lib/utils";
import { Checkbox } from "@/components/ui/checkbox";
import { TableCellSelect, TableRequiredLabel } from "@/components/form-layout";
import { loadOptions } from "./orders";

/** One product on the load order, and where it loads from. */
export interface LoadOrderRow {
  product: string;
  terminal?: string;
  supplier?: string;
  loadingAccount?: string;
  /**
   * Set aside, not deleted. The product is still on the order, so a deleted
   * row would come back blank on the next render.
   */
  excluded?: boolean;
}

/**
 * THE LOAD ORDER TABLE — one row per product, then Terminal, Supplier and
 * Loading Account, each narrowed by the one before it.
 *
 * The delivery order's load order, drawn per product. The Create recurring
 * rule sheet draws its load order BY ACCOUNT instead (Pavan, 2026-09-25) —
 * an account carries several products — so it has its own table. Flush (T1):
 * the card it sits in draws the rim.
 */
export function LoadOrderTable({
  rows,
  onChange,
}: {
  rows: LoadOrderRow[];
  onChange: (product: string, patch: Partial<LoadOrderRow>) => void;
}) {
  return (
    <table className="w-full table-fixed border-collapse">
      <colgroup>
        <col className="w-[44px]" />
        <col className="w-[26%]" />
        <col />
        <col />
        <col />
      </colgroup>
      <thead>
        <tr className="border-b border-border bg-fp-table-header">
          {/* No label: what the tick means is stated by the rows it dims, and
              a header for it would name the exception. */}
          <th aria-hidden />
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel>Product</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel required>Terminal</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel required>Supplier</TableRequiredLabel>
          </th>
          <th className="px-3 py-2.5 text-left">
            <TableRequiredLabel required>Loading Account</TableRequiredLabel>
          </th>
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => {
          /* Narrowed by THIS product, then by what is chosen to its left. */
          const opts = loadOptions([row.product], row.terminal, row.supplier);
          const on = !row.excluded;
          return (
            <tr
              key={row.product}
              className="h-11 border-b border-border last:border-b-0"
            >
              {/* SET ASIDE, NOT DELETED. Unticking dims the row and disables
                  its cells, keeping whatever was chosen for the moment someone
                  ticks it again. */}
              <td className="px-3">
                <Checkbox
                  checked={on}
                  onCheckedChange={(c) =>
                    onChange(row.product, { excluded: c !== true })
                  }
                  aria-label={`Include ${row.product} in the load order`}
                />
              </td>
              <td
                className={cn(
                  "truncate px-3 text-sm",
                  on ? "text-foreground" : "text-muted-foreground line-through"
                )}
              >
                {row.product}
              </td>
              <td className="relative p-0">
                <TableCellSelect
                  value={row.terminal ?? ""}
                  options={opts.terminals}
                  placeholder="Terminal"
                  disabled={!on}
                  aria-label={`Terminal for ${row.product}`}
                  onChange={(v) =>
                    onChange(row.product, {
                      terminal: v,
                      supplier: undefined,
                      loadingAccount: undefined,
                    })
                  }
                />
              </td>
              <td className="relative p-0">
                <TableCellSelect
                  value={row.supplier ?? ""}
                  options={opts.suppliers}
                  placeholder="Supplier"
                  disabled={!on}
                  aria-label={`Supplier for ${row.product}`}
                  onChange={(v) =>
                    onChange(row.product, {
                      supplier: v,
                      loadingAccount: undefined,
                    })
                  }
                />
              </td>
              <td className="relative p-0">
                <TableCellSelect
                  value={row.loadingAccount ?? ""}
                  options={opts.accounts}
                  placeholder="Account"
                  disabled={!on}
                  aria-label={`Loading account for ${row.product}`}
                  onChange={(v) => onChange(row.product, { loadingAccount: v })}
                />
              </td>
            </tr>
          );
        })}
      </tbody>
    </table>
  );
}

import * as React from "react";
import { DateKeyField } from "@/components/ui/date-picker";
import { ChevronDown, Plus, Trash2 } from "lucide-react";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { selectTriggerClasses } from "@/components/ui/select";
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group";
import { DATE_FMT, dateKeyOf, relativeLabel, startOfDay } from "../data";
import type { Schedule } from "./recurring";

/*
  HOW OFTEN — the frequency a rule is built from.

  TWO QUESTIONS, NOT ONE, and keeping them apart is the whole design.

    WHICH DAYS   Sunday through Saturday, as badges. Daily lights all seven;
                 otherwise the reader picks.
    HOW IT REPEATS  weekly, monthly or yearly — and what that means differs
                 enough per choice that each gets its own follow-up rather
                 than one list of twenty phrases.

  A SINGLE DROPDOWN OF PHRASES CANNOT DO THIS. "Monthly On First Thursday" is
  one entry in a list that would need a hundred to cover the real range, and
  every one of them has to be read to be understood. Two badges lit and the
  word "monthly" is understood before it is read.

  THE BADGES ARE THE SAME SEVEN THE LIST SHOWS. A reader who picks S–M–T–W–T
  here sees exactly that shape back in the Frequency column, which is what
  makes the column readable at all.

  EVERY SHAPE STILL COMES OUT AS A `Schedule`, so the list cell, the calendar
  and the generator are untouched by any of this — `toSchedule` is the whole
  seam.
*/

export const WEEKDAYS = [
  { letter: "S", name: "Sunday" },
  { letter: "M", name: "Monday" },
  { letter: "T", name: "Tuesday" },
  { letter: "W", name: "Wednesday" },
  { letter: "T", name: "Thursday" },
  { letter: "F", name: "Friday" },
  { letter: "S", name: "Saturday" },
];

const MONTHS = [
  "January", "February", "March", "April", "May", "June",
  "July", "August", "September", "October", "November", "December",
];

export type Repeat = "weekly" | "monthly" | "yearly" | "cycle";

/** CUSTOM CYCLE (Pavan, 2026-10-06) — 2 to 4 weeks, each with its own days. */
export const CYCLE_LENGTHS = [2, 3, 4];
const DAY_MS = 86_400_000;
/** The Sunday that starts `d`'s week, at midnight. */
const weekStart = (d: Date) => {
  const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
  x.setDate(x.getDate() - x.getDay());
  return x;
};
const keyToDate = (k: string) =>
  new Date(Number(k.slice(0, 4)), Number(k.slice(5, 7)) - 1, Number(k.slice(8, 10)));
/** Which week of the cycle `d` falls in, or -1 before the cycle starts. */
export const cycleWeekOf = (d: Date, startKey: string, length: number) => {
  const n = Math.round((weekStart(d).getTime() - weekStart(keyToDate(startKey)).getTime()) / (7 * DAY_MS));
  return n < 0 ? -1 : n % length;
};
/**
 * DAYS OR DATES (Pavan, 2026-10-01) — the two ways a rule says when. Days is
 * weekdays and how they repeat; Date is dates picked on a calendar and how
 * often that set comes round.
 */
export type FrequencyBasis = "days" | "date";

/** How often the picked dates come round: every N months, 0 = only once. */
export const DATE_REPEATS = [
  { n: 1, label: "Every month" },
  { n: 2, label: "Every 2 months" },
  { n: 3, label: "Every 3 months" },
  { n: 6, label: "Every 6 months" },
  { n: 12, label: "Every year" },
  { n: 0, label: "Does not repeat" },
];

/** 0 = every week (the fifth, partial one included); 1–4 = that week. */
export const MONTH_WEEKS = [
  { n: 0, label: "Every week" },
  { n: 1, label: "First week" },
  { n: 2, label: "Second week" },
  { n: 3, label: "Third week" },
  { n: 4, label: "Fourth week" },
];
export type YearlyMode = "firstMonth" | "specificMonths";

export interface RuleFrequency {
  basis: FrequencyBasis;
  /** DATE basis — the picked calendar dates, as `yyyy-mm-dd`. */
  dates: string[];
  /** DATE basis — every N months; 0 is just the picked dates. */
  dateRepeat: number;
  /** `daily` lights all seven and cannot be unpicked one at a time. */
  dayMode: "daily" | "specific";
  /** 0 = Sunday … 6 = Saturday. */
  days: number[];
  repeat: Repeat;
  /**
   * WEEKLY ONLY — how many drops a week, and a time of day for each.
   *
   * The days say WHEN IN THE WEEK; this says how many runs and at what hour,
   * because two drops on a Monday is a real arrangement and the days alone
   * cannot express it.
   */
  times: string[];
  /**
   * WHICH WEEKS OF THE MONTH (Pavan, 2026-10-01) — checkboxes, one or several.
   * `[0]` is every week and stands alone; ticking a single week drops it.
   */
  monthWeeks: number[];
  yearlyMode: YearlyMode;
  /** 0-based, for `specificMonths`. */
  months: number[];
  /** `null` is "no end date", and it is the default. */
  endKey: string | null;
  /** CYCLE ONLY — one list of weekdays per week of the cycle. */
  cycleWeeks?: number[][];
  /** CYCLE ONLY — a day in the week the cycle's Week 1 is, as `yyyy-mm-dd`. */
  cycleStartKey?: string;
}

export function blankFrequency(): RuleFrequency {
  return {
    dayMode: "specific",
    days: [2],
    repeat: "weekly",
    times: ["08:00"],
    basis: "days",
    dates: [],
    dateRepeat: 1,
    monthWeeks: [1],
    yearlyMode: "firstMonth",
    months: [0],
    endKey: null,
  };
}

/** 1st, 2nd, 3rd, 4th… */
const ordinal = (n: number) =>
  `${n}${n % 10 === 1 && n !== 11 ? "st" : n % 10 === 2 && n !== 12 ? "nd" : n % 10 === 3 && n !== 13 ? "rd" : "th"}`;

const nthWeekdayOfMonth = (d: Date) => Math.floor((d.getDate() - 1) / 7) + 1;

const listNames = (xs: string[]) =>
  xs.length <= 1
    ? (xs[0] ?? "")
    : `${xs.slice(0, -1).join(", ")} and ${xs[xs.length - 1]}`;

/**
 * THE SEAM. Everything downstream — the list's Frequency cell, the calendar,
 * the generator — takes a `Schedule`, so the picker's richer shape is turned
 * into one here and nothing else has to know it exists.
 */
export function toSchedule(f: RuleFrequency): Schedule {
  if (f.basis === "date") {
    /* THE PICKED DATES, AND HOW OFTEN THEY COME ROUND. No weekday pattern,
       so one badge instead of the row. Repeating keeps each date's day of
       the month; one past a month's end (the 31st in April) falls on its
       last day, so no month is skipped. */
    const keys = [...(f.dates ?? [])].sort();
    const every = f.dateRepeat ?? 1;
    const dom = [...new Set(keys.map((k) => Number(k.slice(8, 10))))].sort(
      (a, b) => a - b
    );
    const first = keys[0];
    const monthIndex = (d: Date) => d.getFullYear() * 12 + d.getMonth();
    const firstMonth = first
      ? Number(first.slice(0, 4)) * 12 + Number(first.slice(5, 7)) - 1
      : 0;
    return {
      raw: `date:${every}:${keys.join(",")}`,
      label:
        keys.length === 0
          ? "No dates picked"
          : every === 0
            ? `On ${keys.length} ${keys.length === 1 ? "date" : "dates"}`
            : `${every === 1 ? "Every month" : `Every ${every} months`} on the ${listNames(dom.map(ordinal))}`,
      days: [],
      badge: every === 0 ? "Dates" : "Monthly",
      cadence:
        every === 0
          ? `${keys.length} ${keys.length === 1 ? "date" : "dates"}, no repeat`
          : `${dom.length} ${dom.length === 1 ? "date" : "dates"} ${every === 1 ? "every month" : `every ${every} months`}`,
      hits: (d) => {
        if (keys.length === 0) return false;
        const key = dateKeyOf(d);
        if (every === 0) return keys.includes(key);
        if (key < first) return false;
        if ((monthIndex(d) - firstMonth) % every !== 0) return false;
        const last = new Date(d.getFullYear(), d.getMonth() + 1, 0).getDate();
        return dom.some((x) => Math.min(x, last) === d.getDate());
      },
    };
  }
  if (f.repeat === "cycle") {
    const weeks = f.cycleWeeks ?? [f.days, []];
    const start = f.cycleStartKey ?? dateKeyOf(weekStart(new Date()));
    const short = (ds: number[]) =>
      ds.length === 0 ? "none" : ds.map((x) => WEEKDAYS[x].name.slice(0, 3)).join(", ");
    return {
      raw: `cycle:${start}:${weeks.map((w) => w.join(",")).join("|")}`,
      label: weeks.map((w, i) => `Week ${i + 1}: ${short(w)}`).join(" · "),
      days: [...new Set(weeks.flat())].sort((a, b) => a - b),
      cycle: weeks,
      badge: null,
      cadence: `${weeks.length}-week cycle`,
      hits: (d) => {
        const i = cycleWeekOf(d, start, weeks.length);
        return i >= 0 && weeks[i].includes(d.getDay());
      },
    };
  }
  const days = f.dayMode === "daily" ? [0, 1, 2, 3, 4, 5, 6] : [...f.days];
  const onDay = (d: Date) => days.includes(d.getDay());
  const dayNames = days.map((d) => WEEKDAYS[d].name);

  if (f.repeat === "weekly") {
    const perWeek =
      f.times.length > 1 ? `, ${f.times.length}× a day` : "";
    return {
      raw: `weekly:${days.join(",")}`,
      label:
        f.dayMode === "daily" ? "Every day" : `Every ${listNames(dayNames)}`,
      days,
      badge: f.dayMode === "daily" ? "Daily" : null,
      cadence: `Every week${perWeek}`,
      hits: onDay,
    };
  }

  if (f.repeat === "monthly") {
    const weeks = [...(f.monthWeeks ?? [1])].sort((a, b) => a - b);
    const every = weeks.length === 0 || weeks.includes(0);
    const weekWords = weeks.map((n) => ["", "first", "second", "third", "fourth"][n]);
    const capital = (x: string) => x.charAt(0).toUpperCase() + x.slice(1);
    return {
      raw: `monthly:weeks:${weeks.join(",")}:${days.join(",")}`,
      label: every
        ? `Every ${listNames(dayNames)}`
        : `${capital(listNames(weekWords))} ${listNames(dayNames)} of the month`,
      days,
      badge: null,
      cadence: every
        ? "Every week of the month"
        : `${capital(weekWords.join(", "))} ${weeks.length === 1 ? "week" : "weeks"} of every month`,
      hits: (d) => onDay(d) && (every || weeks.includes(nthWeekdayOfMonth(d))),
    };
  }

  const months = f.yearlyMode === "firstMonth" ? [0] : [...f.months];
  const monthNames = months.map((m) => MONTHS[m]);
  return {
    raw: `yearly:${f.yearlyMode}:${months.join(",")}`,
    label:
      f.yearlyMode === "firstMonth"
        ? "Every January"
        : `Every ${listNames(monthNames)}`,
    days,
    badge: "Yearly",
    cadence:
      f.yearlyMode === "firstMonth"
        ? "First month of every year"
        : `${months.length} ${months.length === 1 ? "month" : "months"} a year`,
    hits: (d) => months.includes(d.getMonth()) && onDay(d),
  };
}

/* ---------------------------------------------------------------------------
 * The picker
 * ------------------------------------------------------------------------ */

function DayBadges({
  value,
  onChange,
  stretch,
}: {
  value: number[];
  onChange: (next: number[]) => void;
  /** Fill the row — the frequency unit is wider (Pavan, 2026-10-16). */
  stretch?: boolean;
}) {
  return (
    <div className={cn("flex gap-1", stretch && "w-full")}>
      {WEEKDAYS.map((d, i) => {
        const on = value.includes(i);
        return (
          <button
            key={i}
            type="button"
            aria-pressed={on}
            aria-label={d.name}
            onClick={() =>
              onChange(
                on ? value.filter((x) => x !== i) : [...value, i].sort()
              )
            }
            className={cn(
              "flex h-8 items-center justify-center rounded-md text-sm font-medium transition-colors",
              stretch ? "min-w-8 flex-1" : "w-8",
              on
                ? "bg-accent-violet text-accent-violet-foreground"
                : "bg-fp-card-1 text-muted-foreground hover:text-foreground"
            )}
          >
            {d.letter}
          </button>
        );
      })}
    </div>
  );
}

function Row({
  label,
  hint,
  children,
}: {
  label: string;
  hint?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <span className="text-sm font-medium text-foreground">{label}</span>
      {children}
      {hint && <span className="text-xs text-muted-foreground">{hint}</span>}
    </div>
  );
}

/**
 * WHICH WEEKS, AS CHECKBOXES IN A DROPDOWN (Pavan, 2026-10-01). One or several
 * weeks; "of the month" is said once, beside the field, not in every option.
 * Every week stands alone — it is all of them, the partial fifth included —
 * so ticking it clears the single weeks and ticking a single week clears it.
 * Picking dates instead is the Date tab, not an option here.
 */
function MonthPartPicker({
  value,
  onChange,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
}) {
  const weeks = value.monthWeeks ?? [1];
  const toggleWeek = (n: number) => {
    let next: number[];
    if (n === 0) next = weeks.includes(0) ? [] : [0];
    else {
      const singles = weeks.filter((x) => x !== 0);
      next = singles.includes(n)
        ? singles.filter((x) => x !== n)
        : [...singles, n].sort((a, b) => a - b);
    }
    onChange({ ...value, monthWeeks: next });
  };
  const summary = weeks.includes(0)
      ? "Every week"
      : weeks.length === 0
        ? "Pick weeks"
        : weeks.length === 1
          ? `${["", "First", "Second", "Third", "Fourth"][weeks[0]]} week`
          : /* SHORT WHEN SEVERAL, so the field never cuts the answer off. */
            `${weeks.map((n) => ["", "1st", "2nd", "3rd", "4th"][n]).join(", ")} weeks`;

  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <div className="flex min-w-0 items-center gap-2">
        <DropdownMenu>
          <DropdownMenuTrigger asChild>
            <button
              type="button"
              aria-label="Which weeks of the month"
              className={cn(selectTriggerClasses, "w-full min-w-0")}
            >
              <span
                className={cn(
                  "truncate",
                  weeks.length === 0 && "text-muted-foreground"
                )}
              >
                {summary}
              </span>
              <ChevronDown className="size-4 shrink-0 opacity-50" />
            </button>
          </DropdownMenuTrigger>
          <DropdownMenuContent
            align="start"
            className="w-(--radix-dropdown-menu-trigger-width) min-w-56"
          >
            {MONTH_WEEKS.map((w) => (
              <DropdownMenuCheckboxItem
                key={w.n}
                checked={weeks.includes(w.n)}
                /* Stays open — several weeks are picked in one visit. */
                onSelect={(e) => e.preventDefault()}
                onCheckedChange={() => toggleWeek(w.n)}
              >
                {w.label}
              </DropdownMenuCheckboxItem>
            ))}
          </DropdownMenuContent>
        </DropdownMenu>
        <span className="shrink-0 text-sm text-muted-foreground">
          of the month
        </span>
      </div>
      {weeks.length === 0 && (
        <p className="text-xs text-status-failed">Pick at least one week.</p>
      )}
    </div>
  );
}

/**
 * THE DATE TAB — dates picked from a strip, and how often that set comes
 * round. Picking the 5th and the 20th with Every month is twice a month.
 *
 * A STRIP, NOT A CALENDAR GRID (Pavan, 2026-10-01). The month runs left to
 * right across the whole width of the unit, as many dates to a line as fit,
 * and wraps; Repeat sits under it, because it is asked after the dates.
 * Each date carries its weekday letter so the strip still reads as a week.
 */
function DatePart({
  value,
  onChange,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
}) {
  /* DATES OF THE MONTH, NOT OF A MONTH (Pavan, 2026-10-20) — 1 to 31, no
     month to step through: the dates repeat every month, or every N. Each
     pick is kept as that date's next turn from today (this month if it's
     still ahead, else next month), which is where the repeat starts. */
  const today = new Date();
  const picked = new Set((value.dates ?? []).map((k) => Number(k.slice(8, 10))));
  const keyOf = (dom: number) => {
    const ahead = dom >= today.getDate();
    const m = new Date(today.getFullYear(), today.getMonth() + (ahead ? 0 : 1), 1);
    return `${m.getFullYear()}-${String(m.getMonth() + 1).padStart(2, "0")}-${String(dom).padStart(2, "0")}`;
  };
  const toggle = (dom: number) => {
    const next = new Set(picked);
    if (next.has(dom)) next.delete(dom);
    else next.add(dom);
    onChange({ ...value, dates: [...next].sort((x, y) => x - y).map(keyOf).sort() });
  };

  return (
    /* THE DATES TAKE THE ROW; REPEAT SITS AT ITS RIGHT EDGE, well apart. */
    <div className="flex items-start gap-12">
      <div className="flex min-w-0 flex-1 flex-col gap-1.5">
        <span className="text-sm font-medium text-foreground">Select dates</span>
        <div className="grid grid-cols-[repeat(auto-fill,minmax(2.5rem,1fr))] gap-1">
          {Array.from({ length: 31 }, (_, i) => {
            const dom = i + 1;
            const on = picked.has(dom);
            return (
              <button
                key={dom}
                type="button"
                aria-pressed={on}
                aria-label={`The ${ordinal(dom)}`}
                onClick={() => toggle(dom)}
                className={cn(
                  "flex h-9 items-center justify-center rounded-md text-sm font-medium tabular-nums outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring/50",
                  on
                    ? "bg-accent-violet text-accent-violet-foreground"
                    : "bg-fp-card-1 text-foreground hover:bg-accent"
                )}
              >
                {dom}
              </button>
            );
          })}
        </div>
        {picked.size === 0 && (
          <p className="text-xs text-status-failed">Pick at least one date.</p>
        )}
      </div>

      <div className="w-62 shrink-0">
        <Row label="Repeat">
          <Select
            value={String(value.dateRepeat ?? 1)}
            onValueChange={(v) => onChange({ ...value, dateRepeat: Number(v) })}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {DATE_REPEATS.map((r) => (
                <SelectItem key={r.n} value={String(r.n)}>
                  {r.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Row>
      </div>
    </div>
  );
}

/** Switching Repeat; into a cycle, the days already picked become Week 1. */
function withRepeat(value: RuleFrequency, repeat: Repeat): RuleFrequency {
  if (repeat !== "cycle" || value.cycleWeeks) return { ...value, repeat };
  const days = value.dayMode === "daily" ? [0, 1, 2, 3, 4, 5, 6] : value.days;
  return {
    ...value,
    repeat,
    cycleWeeks: [days, []],
    cycleStartKey: value.cycleStartKey ?? dateKeyOf(weekStart(new Date())),
  };
}

/**
 * CUSTOM CYCLE (Pavan, 2026-10-06) — Repeat, how many weeks, when Week 1
 * starts, then one row of day badges per week, and the next four weeks as
 * they will run. A week with no days is a week with no delivery.
 */
function CyclePart({
  value,
  onChange,
  part,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
  /* IN THREE PLACES (Pavan, 2026-10-16): the weeks where the day badges
     are, the settings where Repeat is, the preview under both. */
  part: "weeks" | "settings" | "preview";
}) {
  const weeks = value.cycleWeeks ?? [value.days, []];
  const startKey = value.cycleStartKey ?? dateKeyOf(weekStart(new Date()));
  const setWeeks = (next: number[][]) => onChange({ ...value, cycleWeeks: next });
  const fmt = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" });
  const first = weekStart(keyToDate(startKey));
  const preview = Array.from({ length: 4 }, (_, k) => {
    const from = new Date(first.getTime() + k * 7 * DAY_MS);
    const ds = weeks[k % weeks.length];
    return {
      label: fmt.format(from),
      days: ds.length === 0 ? "No delivery" : ds.map((x) => WEEKDAYS[x].name.slice(0, 3)).join(", "),
    };
  });
  if (part === "settings")
    return (
      <div className="grid grid-cols-2 content-start gap-6">
        <Row label="Cycle length">
          <Select
            value={String(weeks.length)}
            onValueChange={(v) => {
              const n = Number(v);
              setWeeks(Array.from({ length: n }, (_, i) => weeks[i] ?? []));
            }}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {CYCLE_LENGTHS.map((n) => (
                <SelectItem key={n} value={String(n)}>
                  {n} weeks
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </Row>
        <Row label="Week 1 starts">
          <DateKeyField
            value={startKey}
            onChange={(key) => onChange({ ...value, cycleStartKey: key })}
          />
        </Row>
      </div>
    );
  if (part === "weeks")
    return (
      <div className="flex flex-col gap-2">
        {weeks.map((w, i) => (
          <div key={i} className="flex items-center gap-3">
            <span className="w-14 shrink-0 text-sm font-medium text-foreground">
              Week {i + 1}
            </span>
            <DayBadges
              stretch
              value={w}
              onChange={(next) => setWeeks(weeks.map((x, j) => (j === i ? next : x)))}
            />
          </div>
        ))}
        {weeks.every((w) => w.length === 0) && (
          <p className="text-xs text-status-failed">Pick at least one day.</p>
        )}
      </div>
    );
  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-sm font-medium text-foreground">Next 4 weeks</span>
      <div className="grid grid-cols-4 gap-2">
        {preview.map((p) => (
          <div
            key={p.label}
            className="flex flex-col rounded-md border border-fp-outline-1 px-3 py-2"
          >
            <span className="text-xs text-muted-foreground">Week of {p.label}</span>
            <span className="truncate text-sm text-foreground">{p.days}</span>
          </div>
        ))}
      </div>
    </div>
  );
}

export function RuleFrequencyPicker({
  value,
  onChange,
}: {
  value: RuleFrequency;
  onChange: (next: RuleFrequency) => void;
}) {
  const set = <K extends keyof RuleFrequency>(k: K, v: RuleFrequency[K]) =>
    onChange({ ...value, [k]: v });

  /* WHAT THEY HAD BEFORE DAILY. Ticking Daily fills all seven; going back to
     Specific with all seven still lit is a "specific days" answer that reads
     as daily, and leaves the reader unpicking six badges to get back to where
     they were. The set they came in with is remembered and handed back. */
  const beforeDaily = React.useRef<number[]>(value.days);

  const days = value.dayMode === "daily" ? [0, 1, 2, 3, 4, 5, 6] : value.days;
  const cycle = value.repeat === "cycle";

  return (
    <div className="flex flex-col gap-5">
      {/* DAYS OR DATE (Pavan, 2026-10-01) — THE DS SEGMENT CONTROL (Pavan,
          2026-10-16), the one the lists use for All / Fuel / Lubricants. */}
      <ToggleGroup
        type="single"
        variant="outline"
        size="sm"
        value={value.basis ?? "days"}
        onValueChange={(v) => v && set("basis", v as FrequencyBasis)}
        aria-label="Days or date"
        className="h-7 w-fit"
      >
        {(["days", "date"] as const).map((k) => (
          <ToggleGroupItem
            key={k}
            value={k}
            /* Greyscale — the DS segment control's own selection. */
            className="h-7 px-2.5 text-xs font-normal data-[state=on]:font-medium"
          >
            {k === "days" ? "Days" : "Date"}
          </ToggleGroupItem>
        ))}
      </ToggleGroup>

      {(value.basis ?? "days") === "date" ? (
        <DatePart value={value} onChange={onChange} />
      ) : (
      <>
      {/* THE DAYS UNIT WIDER, REPEAT NARROWER (Pavan, 2026-10-16). A custom
          cycle swaps its week rows into the same place, and its settings
          into Repeat's — on and off look the same, only the content moves. */}
      <div className="flex items-start gap-15">
        <div className="flex w-[360px] shrink-0 flex-col gap-3">
          {cycle ? (
            <CyclePart part="weeks" value={value} onChange={onChange} />
          ) : (
            <div className="flex flex-col gap-1.5">
              <span className="text-sm font-medium text-foreground">Select day/s</span>
              <DayBadges
                stretch
                value={days}
                onChange={(next) => {
                  if (value.dayMode === "daily") beforeDaily.current = next;
                  onChange({
                    ...value,
                    dayMode: next.length === 7 ? "daily" : "specific",
                    days: next,
                  });
                }}
              />
            </div>
          )}
          {/* DAILY AND CUSTOM CYCLE, SIDE BY SIDE — the word, then its switch
              (Pavan, 2026-10-16). Daily means nothing inside a cycle. */}
          <div className="flex items-center gap-6">
            <label
              className={cn(
                "flex w-fit cursor-pointer items-center gap-2.5 text-sm text-foreground",
                cycle && "cursor-not-allowed opacity-50"
              )}
            >
              Daily
              <Switch
                checked={!cycle && value.dayMode === "daily"}
                disabled={cycle}
                onCheckedChange={(on) => {
                  if (on) beforeDaily.current = value.days;
                  const back = beforeDaily.current;
                  onChange({
                    ...value,
                    dayMode: on ? "daily" : "specific",
                    days: on
                      ? [0, 1, 2, 3, 4, 5, 6]
                      : back.length > 0 && back.length < 7
                        ? back
                        : [],
                  });
                }}
              />
            </label>
            <label className="flex w-fit cursor-pointer items-center gap-2.5 text-sm text-foreground">
              Custom cycle
              <Switch
                checked={cycle}
                onCheckedChange={(on) =>
                  onChange(on ? withRepeat(value, "cycle") : { ...value, repeat: "weekly" })
                }
              />
            </label>
          </div>
          {!cycle && value.dayMode === "specific" && value.days.length === 0 && (
            <p className="text-xs text-status-failed">Pick at least one day.</p>
          )}
        </div>

      {/* THE REST OF THE ROW, FILLED (Pavan, 2026-10-16 — DS ui "A row of
          fields fills its row"): the two fields share it equally, 24px apart. */}
      <div className="flex min-w-0 flex-1 flex-col gap-4">
      {cycle ? (
        <CyclePart part="settings" value={value} onChange={onChange} />
      ) : (
      <div className="grid grid-cols-2 content-start gap-6">
        <Row label="Repeat">
          <Select
            value={value.repeat}
            onValueChange={(v) => onChange(withRepeat(value, v as Repeat))}
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="weekly">Weekly</SelectItem>
              <SelectItem value="monthly">Monthly</SelectItem>
              <SelectItem value="yearly">Yearly</SelectItem>
            </SelectContent>
          </Select>
        </Row>
        {value.repeat === "weekly" && (
          <Row label="Times a day">
            <Select
              value={String(value.times.length)}
              onValueChange={(v) => {
                const n = Number(v);
                const next = Array.from(
                  { length: n },
                  (_, i) => value.times[i] ?? ["08:00", "14:00", "18:00"][i % 3]
                );
                set("times", next);
              }}
            >
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {[1, 2, 3].map((n) => (
                  <SelectItem key={n} value={String(n)}>
                    {n} {n === 1 ? "time" : "times"}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </Row>
        )}

        {value.repeat === "monthly" && (
          <Row label="Which part of the month">
            <MonthPartPicker value={value} onChange={onChange} />
          </Row>
        )}

        {value.repeat === "yearly" && (
          <Row label="Which part of the year">
            <Select
              value={value.yearlyMode}
              onValueChange={(v) => set("yearlyMode", v as YearlyMode)}
            >
              <SelectTrigger className="w-full">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="firstMonth">
                  First month of every year
                </SelectItem>
                <SelectItem value="specificMonths">
                  Specific months of the year
                </SelectItem>
              </SelectContent>
            </Select>
          </Row>
        )}
      </div>
      )}
      {/* WEEKLY, MORE THAN ONCE — a time per drop, under Repeat so it reads
          as part of it (Pavan, 2026-09-25). Two deliveries on one day
          is a real arrangement and the day badges cannot say it. */}
      {value.repeat === "weekly" && value.times.length > 1 && (
        <div className="flex flex-wrap gap-3">
          {value.times.map((t, i) => (
            <div key={i} className="flex min-w-0 flex-col gap-1.5">
              <span className="text-xs font-medium text-muted-foreground">
                Drop {i + 1}
              </span>
              <Input
                type="time"
                className="w-[130px]"
                value={t}
                aria-label={`Time for drop ${i + 1}`}
                onChange={(e) =>
                  set(
                    "times",
                    value.times.map((x, j) => (j === i ? e.target.value : x))
                  )
                }
              />
            </div>
          ))}
        </div>
      )}
      </div>
      </div>

      {cycle && <CyclePart part="preview" value={value} onChange={onChange} />}

      {value.repeat === "yearly" && value.yearlyMode === "specificMonths" && (
        <div className="flex flex-wrap gap-1.5">
          {MONTHS.map((m, i) => {
            const on = value.months.includes(i);
            return (
              <button
                key={m}
                type="button"
                aria-pressed={on}
                onClick={() =>
                  set(
                    "months",
                    on
                      ? value.months.filter((x) => x !== i)
                      : [...value.months, i].sort((a, b) => a - b)
                  )
                }
                className={cn(
                  "rounded-md px-2.5 py-1 text-xs font-medium transition-colors",
                  on
                    ? "bg-accent-violet text-accent-violet-foreground"
                    : "bg-fp-card-1 text-muted-foreground hover:text-foreground"
                )}
              >
                {m.slice(0, 3)}
              </button>
            );
          })}
        </div>
      )}

      </>
      )}

      {/* NO END DATE IS THE DEFAULT, so there is nothing to say until
          somebody wants one — the offer to add one is the whole control. */}
      <div className="flex flex-wrap items-center gap-3">
        {value.endKey === null ? (
          <Button
            variant="ghost"
            size="sm"
            className="-ml-2"
            onClick={() => {
              const d = new Date();
              d.setFullYear(d.getFullYear() + 1);
              set("endKey", d.toISOString().slice(0, 10));
            }}
          >
            <Plus />
            Add an end date
          </Button>
        ) : (
          <div className="flex items-center gap-2">
            {/* AS WIDE AS THE DAY BUTTONS ABOVE — seven 32px buttons and six
                4px gaps, 248px (Pavan, 2026-09-25). */}
            <div className="w-62">
              <DateKeyField value={value.endKey} placeholder="End date" onChange={(key) => set("endKey", key)} />
            </div>
            <Button
              variant="ghost"
              size="icon-sm"
              aria-label="Remove the end date"
              className="text-muted-foreground hover:text-destructive"
              onClick={() => set("endKey", null)}
            >
              <Trash2 />
            </Button>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * THE NEXT DELIVERIES A FREQUENCY MAKES — from today, up to its end date.
 * Shared by every Create recurring rule (3PL, Customer Portal).
 */
export function nextHits(f: RuleFrequency, count = 4, from = startOfDay(new Date())): string[] {
  const sched = toSchedule(f);
  const end = f.endKey ? new Date(`${f.endKey}T00:00`) : null;
  const out: string[] = [];
  for (let i = 0; i < 400 && out.length < count; i++) {
    const d = new Date(from);
    d.setDate(d.getDate() + i);
    if (end && d > end) break;
    if (sched.hits(d)) out.push(dateKeyOf(d));
  }
  return out;
}

/**
 * NEXT 4 DELIVERIES — the strip pinned above a rule form's Create button
 * (Pavan, 2026-10-16), so what the rule will make is always in view.
 */
export function NextDeliveries({ keys }: { keys: string[] }) {
  const today = startOfDay(new Date());
  return (
    <div className="flex flex-col gap-1.5">
      <span className="text-sm font-medium text-foreground">Next 4 deliveries</span>
      <div className="grid grid-cols-4 gap-2">
        {keys.length === 0 ? (
          <span className="col-span-4 text-sm text-muted-foreground">—</span>
        ) : (
          keys.map((k) => {
            const d = new Date(`${k}T00:00`);
            return (
              <div key={k} className="flex flex-col rounded-md border border-fp-outline-1 px-3 py-1.5">
                <span className="text-sm text-foreground">{DATE_FMT.format(d)}</span>
                <span className="text-xs text-muted-foreground">
                  {relativeLabel(Math.round((d.getTime() - today.getTime()) / 86_400_000), d)}
                </span>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}

/* THE FREQUENCY UNIT IN ONE LINE (Pavan, 2026-10-20) — for the list's
   Repeats column and anywhere an order's repeat is named. */
const DAY_SHORT = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
export function scheduleSummary(f: RuleFrequency): string {
  if (f.basis === "date") {
    if (!f.dates.length) return "";
    const th = (n: number) => `${n}${n % 10 === 1 && n !== 11 ? "st" : n % 10 === 2 && n !== 12 ? "nd" : n % 10 === 3 && n !== 13 ? "rd" : "th"}`;
    const doms = [...new Set(f.dates.map((k) => Number(k.slice(8, 10))))].sort((a, b) => a - b).map(th).join(", ");
    const every = f.dateRepeat ?? 1;
    return `${every === 0 ? "Once" : every === 1 ? "Every month" : `Every ${every} months`} · ${doms}`;
  }
  if (f.repeat === "cycle") return `Every ${(f.cycleWeeks ?? []).length || 2} weeks`;
  const days = f.dayMode === "daily" ? "Every day" : f.days.slice().sort().map((d) => DAY_SHORT[d]).join(", ");
  if (!days) return "";
  return f.repeat === "weekly" || f.dayMode === "daily" ? (f.dayMode === "daily" ? days : `Weekly · ${days}`) : `${f.repeat[0].toUpperCase()}${f.repeat.slice(1)} · ${days}`;
}

/** A FREQUENCY CARRIED AS TEXT — an order's `recurrence.frequency`, which
    `parseSchedule` reads back (Pavan, 2026-10-20: the order sheet now uses
    the rule's frequency unit). */
export const encodeFrequency = (f: RuleFrequency) => `rf:${JSON.stringify(f)}`;
export const decodeFrequency = (raw: string): RuleFrequency | null => {
  if (!raw.startsWith("rf:")) return null;
  try {
    return JSON.parse(raw.slice(3)) as RuleFrequency;
  } catch {
    return null;
  }
};

/** AN OLD CADENCE AS THE UNIT (Pavan, 2026-10-20) — orders saved with the
    former frequency list open on what they said. "Custom" and anything else
    unknown start blank. */
const DAY_NAMES = ["Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];
const MONTH_NAMES = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
export function frequencyFromLegacy(raw: string): RuleFrequency | null {
  const base = blankFrequency();
  if (raw === "Daily") return { ...base, dayMode: "daily", days: [0, 1, 2, 3, 4, 5, 6] };
  if (raw === "Every Weekday (Monday To Friday)") return { ...base, days: [1, 2, 3, 4, 5] };
  const w = /^Weekly On (\w+)$/.exec(raw);
  if (w && DAY_NAMES.includes(w[1])) return { ...base, days: [DAY_NAMES.indexOf(w[1])] };
  const m = /^Monthly On (\w+) (\w+)$/.exec(raw);
  if (m && DAY_NAMES.includes(m[2])) {
    const nth = ["First", "Second", "Third", "Fourth"].indexOf(m[1]) + 1;
    return { ...base, repeat: "monthly", monthWeeks: [nth || 1], days: [DAY_NAMES.indexOf(m[2])] };
  }
  const y = /^Annually On (\w+) (\d+)$/.exec(raw);
  if (y && MONTH_NAMES.includes(y[1])) {
    const mo = MONTH_NAMES.indexOf(y[1]);
    const now = new Date();
    const key = `${now.getFullYear()}-${String(mo + 1).padStart(2, "0")}-${String(Number(y[2])).padStart(2, "0")}`;
    return { ...base, basis: "date", dates: [key], dateRepeat: 12 };
  }
  return null;
}

